import type { AlertContextType, AlertProps } from "./alert.types";

import React, { forwardRef, useCallback, useState, useEffect, useMemo } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import {
  Attention as AttentionIcon,
  Close as DefaultCloseIcon,
  Comment as CommentIcon,
  Info as InfoIcon,
  Star as StarIcon,
  Success as SuccessIcon,
  Warning as WarningIcon,
} from "@exp-textura/icons";
import { IconButton } from "@components/icon-button";

import { AlertClasses, StyledAlert } from "./alert.styles";
import { AlertContext, useAlert } from "./hooks/use-alert";

const variantIconMap: Record<string, React.ComponentType<React.SVGProps<SVGSVGElement>>> = {
  default: CommentIcon,
  critical: AttentionIcon,
  info: InfoIcon,
  neutral: StarIcon,
  success: SuccessIcon,
  warning: WarningIcon,
};

const AlertRoot = forwardRef<HTMLDivElement, AlertProps>(
  (
    {
      className,
      variant = "default",
      treatment = "bold",
      type = "edge",
      onClose,
      show: showProp = true,
      children,
      ...props
    }: AlertProps,
    ref: React.ForwardedRef<HTMLDivElement>,
  ) => {
    const theme = useTheme();
    const [show, setShow] = useState(showProp);
    const rootClasses = clsx(
      AlertClasses.root,
      AlertClasses[type],
      {
        [AlertClasses.subtle]: treatment === "subtle",
      },
      className,
    );

    const handleClose = useCallback(() => {
      setShow(false);
      onClose?.();
    }, [onClose]);

    useEffect(() => {
      setShow(showProp);
      if (!showProp) {
        onClose?.();
      }
    }, [onClose, showProp]);

    const contextValue: AlertContextType = useMemo(
      () => ({ handleClose, variant }),
      [handleClose, variant],
    );

    if (!show) return null;

    return (
      <AlertContext.Provider value={contextValue}>
        <StyledAlert
          ref={ref}
          className={rootClasses}
          currentTheme={theme}
          variant={variant}
          {...props}
        >
          {children}
        </StyledAlert>
      </AlertContext.Provider>
    );
  },
);

AlertRoot.displayName = "Alert";

const Title: React.FC<React.HTMLAttributes<HTMLParagraphElement>> = ({ children, className }) => (
  <p className={clsx(AlertClasses.title, className)}>{children}</p>
);
Title.displayName = "Alert.Title";

const Description: React.FC<React.HTMLAttributes<HTMLParagraphElement>> = ({
  children,
  className,
}) => <p className={clsx(AlertClasses.description, className)}>{children}</p>;
Description.displayName = "Alert.Description";

const Content: React.FC<React.HTMLAttributes<HTMLDivElement>> = ({ children, className }) => (
  <div aria-atomic="true" className={clsx(AlertClasses.content, className)} role="alert">
    {children}
  </div>
);
Content.displayName = "Alert.Content";

const Icon: React.FC<
  React.HTMLAttributes<HTMLOrSVGElement> & { children?: React.ReactElement }
> = ({ children, className }) => {
  const { variant } = useAlert();
  const iconClasses = clsx(AlertClasses.icon, className);
  if (children && React.isValidElement(children)) {
    return React.cloneElement(children as React.ReactElement, {
      className: clsx(iconClasses, children.props.className),
    });
  }
  const VariantIcon = variantIconMap[variant] ?? InfoIcon;
  return <VariantIcon className={iconClasses} />;
};
Icon.displayName = "Alert.Icon";

const CloseIconButton: React.FC<React.HTMLAttributes<HTMLButtonElement>> = ({
  children,
  className,
  "aria-label": customAriaLabel,
}) => {
  const { handleClose } = useAlert();
  const buttonClasses = clsx(AlertClasses.closeIconButton, className);

  const commonProps = {
    "aria-label": customAriaLabel || "close current alert",
  };
  return (
    <IconButton
      buttonType="secondary"
      className={buttonClasses}
      size="sm"
      variant="inverse"
      onClick={handleClose}
      {...commonProps}
    >
      {children ? children : <DefaultCloseIcon />}
    </IconButton>
  );
};
CloseIconButton.displayName = "Alert.CloseIconButton";

const Alert = Object.assign(AlertRoot, {
  Title,
  Description,
  Content,
  Icon,
  CloseIconButton,
});

export default Alert;
